with inserted as (
 insert into public.jobs_cms_entries(kind,slug,title_en,title_vi,summary_en,summary_vi,body_en,body_vi,data,status)
 select kind,slug,title_en,title_vi,summary_en,summary_vi,body_en,body_vi,data,'draft'
 from jsonb_to_recordset('[{"kind":"category","slug":"public","title_en":"Public schools","title_vi":"Trường công lập","summary_en":"Teaching recruitment category: Public schools.","summary_vi":"Thông tin tuyển dụng: Trường công lập.","body_en":"","body_vi":"","data":{}},{"kind":"category","slug":"centers","title_en":"Language centers","title_vi":"Trung tâm tiếng Anh","summary_en":"Teaching recruitment category: Language centers.","summary_vi":"Thông tin tuyển dụng: Trung tâm tiếng Anh.","body_en":"","body_vi":"","data":{}},{"kind":"location","slug":"bac-giang","title_en":"Bắc Giang","title_vi":"Bắc Giang","summary_en":"Teaching recruitment location: Bắc Giang.","summary_vi":"Thông tin tuyển dụng: Bắc Giang.","body_en":"","body_vi":"","data":{}},{"kind":"vacancy","slug":"bac-giang","title_en":"English Teacher","title_vi":"Giáo viên tiếng Anh","summary_en":"Bring your energy to a language center and international school in Bắc Giang. A full-time role teaching young learners, with accommodation support and a negotiable salary.","summary_vi":"Giảng dạy tại trung tâm và trường quốc tế ở Bắc Giang. Vị trí toàn thời gian dành cho học sinh nhỏ tuổi, có hỗ trợ chỗ ở và mức lương thỏa thuận.","body_en":"The original listing gives an ASAP start and 50% work permit / temporary residence card support. Confirm the start date and accommodation arrangements with the recruiter.","body_vi":"Tin gốc ghi nhận bắt đầu sớm và hỗ trợ 50% giấy phép lao động / thẻ tạm trú. Xác nhận ngày bắt đầu và chỗ ở với chuyên viên tuyển dụng.","data":{"employer_slug":"","category_slug":"centers","location_slug":"bac-giang","closes_on":"","hours":100,"ages":"4–16","contact_email":"thuyylingg2107@gmail.com","source_url":"https://garyagency.com/offer-in-bac-giang-2/","requirements_en":"Bachelor’s degree\nTESOL or TEFL teaching certificate\nEnglish proficiency certificate (C1, VSTEP, TOEIC, TOEFL, ESOL or equivalent)\nAll required documents must be legalized","requirements_vi":"Bằng cử nhân\nChứng chỉ giảng dạy TESOL hoặc TEFL\nChứng chỉ năng lực tiếng Anh (C1, VSTEP, TOEIC, TOEFL, ESOL hoặc tương đương)\nCác giấy tờ cần thiết phải được hợp pháp hóa","benefits_en":"50% WP / TRC support","benefits_vi":"Hỗ trợ 50% WP / TRC"}},{"kind":"location","slug":"hai-phong","title_en":"Hải Phòng","title_vi":"Hải Phòng","summary_en":"Teaching recruitment location: Hải Phòng.","summary_vi":"Thông tin tuyển dụng: Hải Phòng.","body_en":"","body_vi":"","data":{}},{"kind":"vacancy","slug":"hai-phong","title_en":"Public School English Teacher","title_vi":"Giáo viên tiếng Anh trường công","summary_en":"Find your rhythm in the port city of Hải Phòng with an English teaching role in public schools. The published teaching load is 60 hours per month, with work permit and residence card support.","summary_vi":"Giảng dạy tiếng Anh tại các trường công lập ở thành phố cảng Hải Phòng. Khối lượng giảng dạy được công bố là 60 giờ/tháng, có hỗ trợ giấy phép lao động và thẻ tạm trú.","body_en":"The published start date was 7 September 2026. Ask the recruiter to confirm whether recruitment is still open and discuss the current start date.","body_vi":"Ngày bắt đầu được đăng là 7/9/2026. Liên hệ chuyên viên để xác nhận vị trí còn tuyển và ngày bắt đầu hiện tại.","data":{"employer_slug":"","category_slug":"public","location_slug":"hai-phong","closes_on":"","hours":60,"ages":"","contact_email":"chloevu02@gmail.com","source_url":"https://garyagency.com/%f0%9f%9a%a8-teaching-opportunity-in-hai-phong-%f0%9f%87%bb%f0%9f%87%b3-public-schools-2/","requirements_en":"CV and bachelor’s degree\nTEFL, TESOL, CELTA or equivalent teaching certificate\nShort introduction video\nThe listing names South African, Russian, Moroccan, EU and native English-speaking applicants as preferred; ask the recruiter about eligibility.","requirements_vi":"CV và bằng cử nhân\nChứng chỉ TEFL, TESOL, CELTA hoặc tương đương\nVideo giới thiệu ngắn\nTin gốc ưu tiên ứng viên Nam Phi, Nga, Ma-rốc, EU và người bản ngữ; liên hệ chuyên viên để xác nhận điều kiện.","benefits_en":"WP / TRC support","benefits_vi":"Hỗ trợ WP / TRC"}},{"kind":"location","slug":"hanoi","title_en":"Thạch Thất, Hà Nội","title_vi":"Thạch Thất, Hà Nội","summary_en":"Teaching recruitment location: Thạch Thất, Hà Nội.","summary_vi":"Thông tin tuyển dụng: Thạch Thất, Hà Nội.","body_en":"","body_vi":"","data":{}},{"kind":"vacancy","slug":"hanoi","title_en":"English Teacher in Hanoi","title_vi":"Giáo viên tiếng Anh tại Hà Nội","summary_en":"A full-time public school opportunity in Thạch Thất, Hanoi, for Filipino English teachers. Teach students from grades 1 to 12, with work permit support provided.","summary_vi":"Cơ hội toàn thời gian tại trường công ở Thạch Thất, Hà Nội, dành cho giáo viên tiếng Anh Philippines. Giảng dạy học sinh lớp 1–12, có hỗ trợ giấy phép lao động.","body_en":"Teachers already in Vietnam or able to relocate soon are given priority. Salary is negotiable; confirm the full package directly with the recruiter.","body_vi":"Ưu tiên giáo viên đang ở Việt Nam hoặc có thể sớm chuyển đến. Lương thỏa thuận; xác nhận gói quyền lợi trực tiếp với chuyên viên.","data":{"employer_slug":"","category_slug":"public","location_slug":"hanoi","closes_on":"","hours":100,"ages":"Grades 1–12","contact_email":"thuyylingg2107@gmail.com","source_url":"https://garyagency.com/job-offer-in-thach-that-hanoi/","requirements_en":"This listing is for Filipino English teachers\nBachelor’s degree and a C1 / C2 English certificate\nTEFL, TESOL, CELTA or equivalent is preferred\nGood English communication and a full-time commitment in Hanoi","requirements_vi":"Vị trí dành cho giáo viên tiếng Anh Philippines\nBằng cử nhân và chứng chỉ tiếng Anh C1 / C2\nƯu tiên chứng chỉ TEFL, TESOL, CELTA hoặc tương đương\nGiao tiếp tiếng Anh tốt và cam kết làm việc toàn thời gian tại Hà Nội","benefits_en":"100% work permit support","benefits_vi":"Hỗ trợ 100% giấy phép lao động"}},{"kind":"location","slug":"dong-nai","title_en":"Định Quán, Đồng Nai","title_vi":"Định Quán, Đồng Nai","summary_en":"Teaching recruitment location: Định Quán, Đồng Nai.","summary_vi":"Thông tin tuyển dụng: Định Quán, Đồng Nai.","body_en":"","body_vi":"","data":{}},{"kind":"vacancy","slug":"dong-nai","title_en":"Full-time English Teacher","title_vi":"Giáo viên tiếng Anh toàn thời gian","summary_en":"Teach kindergarten and language center classes in Định Quán, Đồng Nai. The listing includes free accommodation, teaching materials and support with invitation letters, visas and 50% of WP / TRC costs.","summary_vi":"Giảng dạy tại trường mầm non và trung tâm tiếng Anh ở Định Quán, Đồng Nai. Tin tuyển dụng có chỗ ở miễn phí, tài liệu giảng dạy, hỗ trợ thư mời, visa và 50% chi phí WP / TRC.","body_en":"The listing specifies weekday daytime and evening classes plus Saturday classes, with Sunday off. Confirm your exact timetable and start date with the recruiter.","body_vi":"Tin tuyển dụng có lớp ban ngày và buổi tối trong tuần, thêm thứ Bảy, nghỉ Chủ nhật. Xác nhận thời khóa biểu và ngày bắt đầu với chuyên viên.","data":{"employer_slug":"","category_slug":"centers","location_slug":"dong-nai","closes_on":"","hours":100,"ages":"3–18","contact_email":"chloevu02@gmail.com","source_url":"https://garyagency.com/%f0%9f%8c%9f-full-time-english-teacher-needed-dong-nai-%f0%9f%8c%9f-4/","requirements_en":"University degree; English major preferred\nTESOL, CELTA or equivalent\nTeaching experience and relevant certificates\nC1 certificate / IELTS is preferred","requirements_vi":"Bằng đại học; ưu tiên chuyên ngành tiếng Anh\nChứng chỉ TESOL, CELTA hoặc tương đương\nKinh nghiệm giảng dạy và chứng chỉ liên quan\nƯu tiên chứng chỉ C1 / IELTS","benefits_en":"Free accommodation","benefits_vi":"Chỗ ở miễn phí"}},{"kind":"location","slug":"thai-nguyen","title_en":"Thái Nguyên","title_vi":"Thái Nguyên","summary_en":"Teaching recruitment location: Thái Nguyên.","summary_vi":"Thông tin tuyển dụng: Thái Nguyên.","body_en":"","body_vi":"","data":{}},{"kind":"vacancy","slug":"thai-nguyen","title_en":"Native English Teacher","title_vi":"Giáo viên tiếng Anh bản ngữ","summary_en":"A language center role in Thái Nguyên City for a native English speaker. Teach learners aged 3–15, with a published housing allowance of 2,000,000 VND per month and 50% WP / TRC support.","summary_vi":"Vị trí tại trung tâm tiếng Anh ở thành phố Thái Nguyên dành cho giáo viên bản ngữ. Học sinh từ 3–15 tuổi, hỗ trợ tiền nhà 2.000.000 VNĐ/tháng và 50% WP / TRC theo tin gốc.","body_en":"Salary is negotiable and paid monthly. Confirm the current availability, start date and housing arrangements with the recruiter.","body_vi":"Lương thỏa thuận, thanh toán hằng tháng. Xác nhận vị trí còn tuyển, ngày bắt đầu và chỗ ở với chuyên viên.","data":{"employer_slug":"","category_slug":"centers","location_slug":"thai-nguyen","closes_on":"","hours":100,"ages":"3–15","contact_email":"chloevu02@gmail.com","source_url":"https://garyagency.com/native-english-teacher-needed-thai-nguyen-2/","requirements_en":"Native English speaker\nBachelor’s degree\nCELTA, TESOL, TEFL or equivalent\nCV, degree, teaching certificate and introduction video","requirements_vi":"Người nói tiếng Anh bản ngữ\nBằng cử nhân\nChứng chỉ CELTA, TESOL, TEFL hoặc tương đương\nCV, bằng cấp, chứng chỉ giảng dạy và video giới thiệu","benefits_en":"Housing allowance","benefits_vi":"Hỗ trợ tiền nhà"}}]'::jsonb) as x(kind text,slug text,title_en text,title_vi text,summary_en text,summary_vi text,body_en text,body_vi text,data jsonb)
 on conflict(kind,slug) do nothing returning *
) insert into public.jobs_cms_revisions(entry_id,version,status,snapshot) select id,version,status,to_jsonb(inserted) from inserted;
commit;
